class Solution {
public:
    vector<int> countServers(int n, vector<vector<int>>& logs, int x, vector<int>& queries) {
        sort(logs.begin(), logs.end(), [](const auto& a, const auto& b) {
            return a[1] < b[1];
        });
        int q = queries.size();
        vector<pair<int, int>> q_sorted(q);
        for (int i = 0; i < q; ++i) q_sorted[i] = {queries[i], i};
        sort(q_sorted.begin(), q_sorted.end());
        vector<int> ans(q, 0);
        unordered_map<int, int> active;
        int left = 0, right = 0, num_logs = logs.size();
        for (const auto& [q_time, q_idx] : q_sorted) {
            while (right < num_logs && logs[right][1] <= q_time) {
                active[logs[right][0]]++;
                right++;
            }
            while (left < num_logs && logs[left][1] < q_time - x) {
                int srv = logs[left][0];
                if (--active[srv] == 0) active.erase(srv);
                left++;
            }
            ans[q_idx] = n - (int)active.size();
        }
        return ans;
    }
};

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] countServers(int n, int[][] logs, int x, int[] queries) {
        Arrays.sort(logs, (a, b) -> Integer.compare(a[1], b[1]));
        int q = queries.length;
        Integer[] qIdx = new Integer[q];
        for (int i = 0; i < q; i++) qIdx[i] = i;
        Arrays.sort(qIdx, (a, b) -> Integer.compare(queries[a], queries[b]));
        int[] ans = new int[q];
        Map<Integer, Integer> active = new HashMap<>();
        int left = 0, right = 0, numLogs = logs.length;
        for (int idx : qIdx) {
            int qTime = queries[idx];
            while (right < numLogs && logs[right][1] <= qTime) {
                active.put(logs[right][0], active.getOrDefault(logs[right][0], 0) + 1);
                right++;
            }
            while (left < numLogs && logs[left][1] < qTime - x) {
                int srv = logs[left][0];
                int cnt = active.get(srv) - 1;
                if (cnt == 0) active.remove(srv);
                else active.put(srv, cnt);
                left++;
            }
            ans[idx] = n - active.size();
        }
        return ans;
    }
}

var countServers = function(n, logs, x, queries) {
    logs.sort((a, b) => a[1] - b[1]);
    const q = queries.length;
    const qSorted = Array.from({ length: q }, (_, i) => [queries[i], i]);
    qSorted.sort((a, b) => a[0] - b[0]);
    const ans = new Array(q).fill(0);
    const active = new Map();
    let left = 0, right = 0;
    const numLogs = logs.length;
    for (const [qTime, qIdx] of qSorted) {
        while (right < numLogs && logs[right][1] <= qTime) {
            const srv = logs[right][0];
            active.set(srv, (active.get(srv) || 0) + 1);
            right++;
        }
        while (left < numLogs && logs[left][1] < qTime - x) {
            const srv = logs[left][0];
            const cnt = active.get(srv) - 1;
            if (cnt === 0) active.delete(srv);
            else active.set(srv, cnt);
            left++;
        }
        ans[qIdx] = n - active.size;
    }
    return ans;
};
